/* The marketplace catalog's shape: how many products each category and
 * subcategory gets, and, per product type, everything the generator needs to
 * write believable data (spec fields, key features, variants, price band) and
 * everything the image step needs to find matching photos (search query and
 * the words a photo's description must / must not contain).
 *
 * Categories and subcategory ids are the app's own (public/js/data.js), so
 * generated products land in the existing browse pages. Counts sum to 1000.
 * Adding a product type is a data edit here, nothing else.
 */

const COLORS = ['Black', 'White', 'Silver', 'Navy', 'Forest Green', 'Sand', 'Rose', 'Charcoal'];
const SOFT_COLORS = ['Ivory', 'Sage', 'Dusty Blue', 'Terracotta', 'Charcoal', 'Oat'];
const APPAREL = ['XS', 'S', 'M', 'L', 'XL', 'XXL'];
const SHADES = ['Ivory', 'Beige', 'Honey', 'Caramel', 'Mocha'];

