export const CATEGORY_NAMES = {
  electronics: 'Electronics', fashion: 'Fashion', beauty: 'Beauty', home: 'Home',
  sports: 'Sports', groceries: 'Groceries', accessories: 'Accessories',
};

/* Category/subcategory → target count, e.g. { electronics: { audio: 40, ... } }. */
export function targetCounts() {
  const out = {};
  for (const cat of Object.keys(TAXONOMY)) {
    out[cat] = {};
    for (const sub of Object.keys(TAXONOMY[cat])) out[cat][sub] = TAXONOMY[cat][sub].count;
  }
  return out;
}

export function totalTarget() {
  return Object.values(targetCounts()).reduce((n, c) => n + Object.values(c).reduce((a, b) => a + b, 0), 0);
}
